import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"打包与发布","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/packaging.md","filePath":"zh-CN/dev-guide/packaging.md","lastUpdated":1785993908000}'),n={name:"zh-CN/dev-guide/packaging.md"};function l(d,s,o,h,p,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="打包与发布" tabindex="-1">打包与发布 <a class="header-anchor" href="#打包与发布" aria-label="Permalink to &quot;打包与发布&quot;">​</a></h1><h2 id="插件是如何被发现的" tabindex="-1">插件是如何被发现的 <a class="header-anchor" href="#插件是如何被发现的" aria-label="Permalink to &quot;插件是如何被发现的&quot;">​</a></h2><p>App 启动时会扫描自己的 <code>Plugins/</code> 文件夹(与 <code>Lertaro.App.exe</code> 同级)里的每一个 <code>.dll</code>，查找实现了 <code>IPlugin</code> 的类型。没有单独的清单文件——程序集本身，加上它的类型实现了哪些 SDK 接口，就是完整的契约。</p><h2 id="携带插件自己的依赖库" tabindex="-1">携带插件自己的依赖库 <a class="header-anchor" href="#携带插件自己的依赖库" aria-label="Permalink to &quot;携带插件自己的依赖库&quot;">​</a></h2><p>如果你的插件需要自己的托管或原生依赖 DLL(比如数据库驱动、原生互操作库……)，把它们放进 App 的 <code>Plugins/</code> 文件夹下你插件自己的一个子目录里——比如 <code>Plugins/YourPlugin/YourPlugin.dll</code> 连同它的依赖都放在同一层——而不是平铺在 <code>Plugins/</code> 根目录下。加载器会递归扫描 <code>Plugins/</code>，之后 <code>Assembly.LoadFrom</code> 自带的同目录依赖探测就会自动解析你的依赖，不会把它们混进其他插件的加载目录里。</p><p>扫描过程中遇到的非 .NET 文件(比如原生 DLL <code>e_sqlite3.dll</code>)是预期之内的，会以 <code>Debug</code> 级别记录，而不是 <code>Error</code>——只有真正加载失败的托管程序集才会记 <code>Error</code>。</p><p>完整的真实例子可以看 <code>BrowserData</code> 插件的 <code>.csproj</code>:它就是这样打包 <code>Microsoft.Data.Sqlite</code> 及其原生依赖 <code>SQLitePCLRaw</code>/<code>e_sqlite3.dll</code> 的，还带了 PostBuild/PostPublish 目标，不管是哪种构建方式生成的，都会把它们归拢进自己的子文件夹。</p><h2 id="开发时自动化复制" tabindex="-1">开发时自动化复制 <a class="header-anchor" href="#开发时自动化复制" aria-label="Permalink to &quot;开发时自动化复制&quot;">​</a></h2><p>Lertaro 自带的插件(<code>CoreExtensions</code>、<code>PinyinAlias</code>)都在各自的 <code>.csproj</code> 里用一个 PostBuild 目标自动化了部署步骤，把刚编译好的 DLL 直接复制到 App 自己输出目录下的 <code>Plugins/</code> 文件夹，这样重新编译后下次启动就能立刻生效:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>把目标路径改成你自己的构建输出和 Lertaro App 安装位置实际所在的路径即可。</p><h2 id="内嵌语言包" tabindex="-1">内嵌语言包 <a class="header-anchor" href="#内嵌语言包" aria-label="Permalink to &quot;内嵌语言包&quot;">​</a></h2><p>如果插件实现了 <code>ITranslationProvider</code>(见<a href="./sdk/ui-extensions.html">界面与预览扩展</a>)，把语言包 JSON 文件作为内嵌资源打包，而不是散落的独立文件，这样它们才会跟着 DLL 一起分发:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>TranslationService.LoadEmbeddedTranslations</code>(见<a href="./sdk/services.html">宿主服务</a>)会在运行时按文化名称从程序集里把它们读出来。</p><h2 id="版本号" tabindex="-1">版本号 <a class="header-anchor" href="#版本号" aria-label="Permalink to &quot;版本号&quot;">​</a></h2><p>给插件的 <code>.csproj</code> 加上 <code>&lt;Version&gt;</code>；它会显示在<strong>设置 → 插件</strong>里对应插件的卡片上，旁边还会显示你的插件是针对哪个 <code>PluginSdk</code> 版本编译的——在 SDK 接口发生变化时，这对确认兼容性很有用。</p>`,17)])])}const E=i(n,[["render",l]]);export{c as __pageData,E as default};
